 m4_runtime::Runtime&r;m4_onexit::Session&session;State&s;Sink sink;void*opaque;DWORD thread=GetCurrentThreadId();bool active{},failed{},complete{};unsigned root_frame{},root_return{},last_return{};std::vector<Access>accesses;std::vector<std::array<unsigned,8>>call_store_timing;std::vector<Frame>frames;std::vector<std::array<unsigned,8>>imports,calls;
