 unsigned word(unsigned a){return r.memory().load<unsigned>({a});}
 const literal::Instruction&instruction(unsigned pc){need(active&&pc!=0x5ac128&&pc!=0x5ac12c&&pc!=0x5ac131&&pc!=0x5ac136&&pc!=0x5ac137&&pc!=0x5ac13c&&pc!=0x5ac13f,"Finite normal actual sentinel onexit domain; cold DLL route denied");const auto*row=literal::instruction(pc);need(row,"Complete finite physical version source instruction");std::array<std::byte,16>b{};r.memory().read({pc},std::span(b.data(),row->size));for(unsigned k=0;k<row->size;++k)need(std::to_integer<unsigned>(b[k])==row->bytes[k],"Every complete actual source instruction byte");return *row;}
 std::uint64_t read(unsigned a,unsigned n){authority();const auto pc=s.gpr.rip.dword;const auto&row=instruction(pc);need(n&&n<=4&&accesses.size()<300000,"Finite literal source scalar width/budget");std::array<std::byte,4>b{};r.memory().read({a},std::span(b.data(),n));std::uint64_t v{};std::memcpy(&v,b.data(),n);accesses.push_back({pc,a,v,n,0});for(const auto&i:literal::imports)if(pc==i.pc){need(n==4&&a==i.slot&&v==i.raw,"Same complete source thunk import operand");imports.push_back({pc,a,unsigned(v),i.projected,unsigned(frames.size()),unsigned(accesses.size()-1),0,0});return i.projected;}if(row.ret)last_return=pc;return v;}
