extern "C" std::uint8_t mw34_version_game_read8(void*p,unsigned a){return std::uint8_t(owner(p).read(a,1));}extern "C" std::uint16_t mw34_version_game_read16(void*p,unsigned a){return std::uint16_t(owner(p).read(a,2));}extern "C" unsigned mw34_version_game_read32(void*p,unsigned a){return unsigned(owner(p).read(a,4));}
