extern "C" void*mw34_version_game_call(State*s,unsigned a,void*p){auto&c=owner(p);need(&c.s==s,"Exact persistent version State");return c.dispatch(a,false);}extern "C" void*mw34_version_game_jump(State*s,unsigned a,void*p){auto&c=owner(p);need(&c.s==s,"Exact persistent version State");return c.dispatch(a,true);}extern "C" void*mw34_version_game_missing(State*s,unsigned a,void*p){return mw34_version_game_jump(s,a,p);}extern "C" void*mw34_version_game_return(State*s,unsigned a,void*p){auto&c=owner(p);need(&c.s==s,"Exact persistent source State");c.returned(a);return p;}
